-- UCIP initial schema (PostgreSQL 15+).
--
-- Mirrors db/migrations/0001_init.sql at the repository root. If you diverge, you must write a
-- migration — do not edit this file once applied.
--
-- Design notes
-- * UUID primary keys so ids can be generated client-side and merged without coordination.
-- * Cited data: every derived value can be traced to rows in match_events / dataset_records.
-- * JSONB is used only for genuinely schemaless payloads (raw upload rows, report bodies).
-- * Row-level security is enabled on tenant-scoped tables but POLICIES ARE NOT YET WRITTEN
--   (see docs/security/KNOWN_GAPS.md). Do not expose the database directly until they are.

create extension if not exists "pgcrypto";

-- ── reference data ────────────────────────────────────────────────────────────
create table if not exists teams (
  id            uuid primary key default gen_random_uuid(),
  name          text not null,
  short_name    text not null unique,
  country       text not null default 'India',
  is_user_team  boolean not null default false,
  primary_color text,
  created_at    timestamptz not null default now()
);

create table if not exists venues (
  id         uuid primary key default gen_random_uuid(),
  name       text not null unique,
  city       text not null,
  country    text not null default 'India',
  capacity   integer,
  created_at timestamptz not null default now()
);

create table if not exists players (
  id            uuid primary key default gen_random_uuid(),
  name          text not null,
  team_id       uuid references teams(id) on delete set null,
  role          text not null check (role in ('batter','bowler','all-rounder','wicket-keeper')),
  batting_style text,
  bowling_style text,
  date_of_birth date,
  nationality   text not null default 'India',
  is_uncapped   boolean not null default true,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now(),
  constraint players_name_dob_unique unique (name, date_of_birth)
);
create index if not exists players_team_idx on players (team_id);
create index if not exists players_role_age_idx on players (role, date_of_birth);

create table if not exists matches (
  id            uuid primary key default gen_random_uuid(),
  competition   text not null,
  season        text not null,
  played_on     date not null,
  venue_id      uuid references venues(id) on delete set null,
  home_team_id  uuid references teams(id) on delete set null,
  away_team_id  uuid references teams(id) on delete set null,
  toss_winner_id uuid references teams(id) on delete set null,
  result        text,
  created_at    timestamptz not null default now()
);
create index if not exists matches_date_idx on matches (played_on desc);

-- ── ball-level evidence (the source of truth for every derived metric) ────────
create table if not exists match_events (
  id          bigserial primary key,
  match_id    uuid not null references matches(id) on delete cascade,
  innings     smallint not null check (innings between 1 and 4),
  over_number smallint not null,
  ball_number smallint not null,
  batter_id   uuid references players(id) on delete set null,
  bowler_id   uuid references players(id) on delete set null,
  runs_batter smallint not null default 0,
  runs_extras smallint not null default 0,
  is_wicket   boolean not null default false,
  dismissal   text,
  phase       text check (phase in ('powerplay','middle','death')),
  created_at  timestamptz not null default now()
);
create index if not exists match_events_match_idx on match_events (match_id, innings, over_number);
create index if not exists match_events_batter_idx on match_events (batter_id);
create index if not exists match_events_bowler_idx on match_events (bowler_id);

-- ── ingestion ─────────────────────────────────────────────────────────────────
create table if not exists datasets (
  id             uuid primary key default gen_random_uuid(),
  name           text not null,
  source         text not null,
  status         text not null default 'draft'
                 check (status in ('draft','validated','approved','rejected','merged')),
  quality_score  numeric(5,2),
  row_count      integer not null default 0,
  uploaded_by    uuid references users(id) on delete set null,
  approved_by    uuid references users(id) on delete set null,
  created_at     timestamptz not null default now(),
  approved_at    timestamptz
);

create table if not exists dataset_records (
  id          uuid primary key default gen_random_uuid(),
  dataset_id  uuid not null references datasets(id) on delete cascade,
  player_id   uuid references players(id) on delete set null,
  raw         jsonb not null,               -- exactly what the file said
  mapped      jsonb not null default '{}',  -- platform fields after mapping
  issues      jsonb not null default '[]',  -- validation findings with severity
  created_at  timestamptz not null default now()
);
create index if not exists dataset_records_dataset_idx on dataset_records (dataset_id);
create index if not exists dataset_records_player_idx on dataset_records (player_id);

-- ── identity & governance ─────────────────────────────────────────────────────
create table if not exists users (
  id             uuid primary key default gen_random_uuid(),
  email          citext not null unique,
  name           text not null,
  role           text not null default 'viewer'
                 check (role in ('owner','analyst','scout','viewer')),
  password_hash  text not null,             -- scrypt: salt:hash, never plaintext
  totp_secret    text,                      -- encrypted at rest when the app supports it
  is_active      boolean not null default true,
  created_at     timestamptz not null default now()
);

create table if not exists sessions (
  id          uuid primary key default gen_random_uuid(),
  user_id     uuid not null references users(id) on delete cascade,
  token_hash  text not null unique,         -- the cookie value is never stored in plaintext
  expires_at  timestamptz not null,
  ip_hash     text,
  created_at  timestamptz not null default now()
);
create index if not exists sessions_user_idx on sessions (user_id);

create table if not exists audit_log (
  id         bigserial primary key,
  actor_id   uuid references users(id) on delete set null,
  action     text not null,
  target     text,
  metadata   jsonb not null default '{}',
  ip_hash    text,
  created_at timestamptz not null default now()
);
create index if not exists audit_log_created_idx on audit_log (created_at desc);

-- ── outputs ───────────────────────────────────────────────────────────────────
create table if not exists reports (
  id           uuid primary key default gen_random_uuid(),
  title        text not null,
  kind         text not null check (kind in ('talent','player','team','venue')),
  sections     jsonb not null,
  quality      smallint,
  created_by   uuid references users(id) on delete set null,
  created_at   timestamptz not null default now()
);

create table if not exists shortlists (
  id         uuid primary key default gen_random_uuid(),
  name       text not null,
  owner_id   uuid references users(id) on delete set null,
  player_ids uuid[] not null default '{}',
  notes      text,
  created_at timestamptz not null default now()
);

create table if not exists testimonials (
  id          uuid primary key default gen_random_uuid(),
  author      text not null,
  role        text,
  quote       text not null,
  status      text not null default 'draft' check (status in ('draft','published','hidden')),
  is_sample   boolean not null default false,
  created_at  timestamptz not null default now()
);

create table if not exists feedback_submissions (
  id          uuid primary key default gen_random_uuid(),
  reference   text not null unique,          -- FB-XXXXXX shown to the submitter
  name        text not null,
  email       text not null,
  topic       text not null,
  message     text not null,
  status      text not null default 'new' check (status in ('new','acknowledged','closed')),
  ip_hash     text,
  created_at  timestamptz not null default now()
);

-- ── tenant scoping: enabled, policies pending (see docs/security/KNOWN_GAPS.md) ─
alter table players        enable row level security;
alter table datasets       enable row level security;
alter table dataset_records enable row level security;
alter table reports        enable row level security;
alter table shortlists     enable row level security;
-- TODO(phase 3): create policies per organisation once `organisations` exists.
